// Full CLI + Python API reference data for the docs/api pages.
// Cross-checked against src/hypernix/interfaces/cli.py at time of writing.

export const CLI_COMMANDS = [
  { cmd: 'hypernix all', args: '[--repo-id <id>] [--model-dir <dir>] [--output-dir <dir>] [--quants fp32 fp16 ...] [--upload-to <repo>]', desc: 'Default pipeline: download -> convert -> [quantize]. Runs when no subcommand is given.' },
  { cmd: 'hypernix download', args: '[--repo-id <id>] [--revision <rev>] [--local-dir <dir>] [--cache-dir <dir>] [--token <tok>] [--quiet]', desc: 'Fetch a HuggingFace snapshot to local disk (or HF cache).' },
  { cmd: 'hypernix convert', args: '--model-dir <dir> --output <path> [--dtype fp16|fp32] [--arch <name>] [--name <name>]', desc: 'Produce an fp32 / fp16 GGUF from a local snapshot.' },
  { cmd: 'hypernix quantize', args: '--source <path> --output <path> --type <q4_k_m|q8_0|...> [--threads N] [--auto]', desc: 'Run llama-quantize on an fp16 / fp32 GGUF.' },
  { cmd: 'hypernix verify', args: '<file.gguf> [--tensors]', desc: 'Read-validate a GGUF and print its headers (+ tensor list with --tensors).' },
  { cmd: 'hypernix info', args: '[--gguf <file.gguf>]', desc: 'Package + Python + torch info, plus a GGUF header summary if given a file.' },
  { cmd: 'hypernix upload', args: '--repo-id <dest> [--token <tok>] [--private] [--commit-message <msg>] <files...>', desc: 'Push one or more files to a HuggingFace repo.' },
  { cmd: 'hypernix doctor', args: '[--fix]', desc: 'Environment diagnostic (Python/torch/deps/llama-quantize path). --fix installs missing runtime deps.' },
  { cmd: 'hypernix fetch-llama-quantize', args: '[--force] [--auto] [--search-releases N]', desc: 'Pre-seed the llama-quantize binary cache.' },
  { cmd: 'hypernix train init', args: '--out-dir <dir> [--vocab-size N] [--hidden-size N] [--num-hidden-layers N] [--num-attention-heads N]', desc: 'Initialize a fresh HyperNix snapshot from scratch.' },
  { cmd: 'hypernix train expand', args: '--src-dir <dir> --dst-dir <dir> [--hidden-size N] [--num-hidden-layers N]', desc: 'Warm-start a bigger model from a smaller checkpoint.' },
  { cmd: 'hypernix train run', args: '--model-dir <dir> --dataset <file> --out-dir <dir> [--steps N] [--batch-size N] [--lr <f>]', desc: 'Run a minimal causal-LM training loop.' },
  { cmd: 'hypernix generate', args: '--model-dir <dir> [--prompt <text>] [--max-new-tokens N] [--temperature <f>]', desc: 'Sample text from a local snapshot. No chat template, no stop-sequence trimming.' },
  { cmd: 'hypernix oven', args: '[--repo-id <id>|--model-dir <dir>] [--prompt <text>] [--fill-prefix <text> --fill-suffix <text>] [--save-pt <path>]', desc: 'Code-generation wrapper: preheat + complete or fill-in-the-middle in one call.' },
  { cmd: 'hypernix chat', args: '[--repo-id <id>|--model-dir <dir>] [--system <text>] [--message <text>]', desc: 'Interactive chat REPL (or single-turn with --message) against any supported model.' },
  { cmd: 'hypernix brew', args: '<recipe.json> [--set KEY=VALUE ...]  |  new / list / train / export ...', desc: 'A JSON recipe path runs the one-shot instant_pot pipeline; otherwise dispatches to the brewer architecture-builder CLI.' },
  { cmd: 'hypernix pipeline', args: '[--audio <file> | --active] [--asr <engine>] [--llm <model>] [--tts <engine>]', desc: 'ASR -> LLM -> TTS pipeline. Known limitation: --llm is currently ignored — the LLM stage is a hardcoded stub that returns a canned/simulated reply, not real model output.' },
  { cmd: 'hypernix assistant', args: '[--voice] [--model <name>]', desc: 'Interactive assistant REPL. Chat turns dispatch through the same provider registry as hyped (local snapshot, local GGUF, or cloud API), so --model selects a real model. Commands: /model, /persona, /system [cmd], /voice (spoken replies), /listen (mic input), /reset, /save.' },
  { cmd: 'hypernix cli', args: '[--simple]', desc: 'Interactive TUI/CLI menu covering all HyperNix operations (rich UI by default, --simple for a plain-text menu).' },
  { cmd: 'hypernix tvtop', args: '[options — see --help]', desc: 'Classic live training dashboard TUI (tails a training log).' },
  { cmd: 'hypernix cctvtop', args: '[options — see --help]', desc: 'Python training dashboard with hardware metrics and optional VNC.' },
  { cmd: 'hypernix fizzle', args: '[options — see --help]  (alias: fiz)', desc: 'Fuzed Architecture module — fuse/merge models and LoRAs.' },
  { cmd: 'hypernix camo', args: '-Lmodel <model> [-Ai] [-M <evaluator>] [-Sp <system prompt>] [-s N]  (alias: camouflage)', desc: 'RLHF/RLAF alignment scaffolding — optional AI-assisted (-Ai) evaluator scoring.' },
  { cmd: 'hypernix prot', args: '[options — see --help]  (alias: protect)', desc: 'Hardware health monitoring and protection module.' },
  { cmd: 'hypernix net', args: 'connect <ip>  |  mport <port>  |  export <port> [--apply]  |  tail acheck|stop <file> [-r]', desc: 'Distributed network manager — Tailscale mesh connect/export + remote log tailing.' },
  { cmd: 'hypernix wiki', args: '[<module>] [-q] [-b] [--version] [--search <keyword>]', desc: 'Documentation browser — reads docstrings straight from installed source, so it does not go stale the way this page can.' },
  { cmd: 'hypernix vera', args: '[options — see --help]', desc: 'Vera assistant CLI.' },
  { cmd: 'hypernix scavenger', args: '[--keywords <csv>] [--max-storage <GB>] [--min-likes N] [--data-type jsonl|parquet|csv] [--download <id>]', desc: 'Search and pull HuggingFace datasets under storage/quality budgets.' },
  { cmd: 'hypernix config', args: '[options — see --help]', desc: 'Configuration management for HyperNix defaults.' },
  { cmd: 'hypernix gkey', args: 'create [--type user|service] [--scopes <csv>] [--expires YYYY-MM-DD]  |  revoke <key_id>  |  list', desc: 'Gatekeeper + Keymaster unified CLI for API key issuance, scoping, and revocation.' },
  { cmd: 'hypernix map', args: '[options — see --help]', desc: 'Steampunk schematic TUI — dials/pipes/steam visualization of model + training state.' },
  { cmd: 'hypernix websearch', args: '<query...> [-n <max results>] [-e auto|duckduckgo|bing] [--json]', desc: 'Non-API web search utility (no search-provider API key required).' },
  { cmd: 'hypernix stml', args: '--vram <GB> [--params <B>] [--batch-size N] [--precision fp32|fp16|int8|int4]', desc: 'Calculate a trainable context length given available VRAM and model size.' },
]

// Companion console scripts installed alongside `hypernix` (see [project.scripts]
// in pyproject.toml) — these are separate executables, not `hypernix <subcommand>`.
export const COMPANION_SCRIPTS = [
  { cmd: 'hnx', desc: 'Short alias for hypernix.' },
  { cmd: 'hypernix-quantize', desc: 'Alias for hypernix (historical name).' },
  { cmd: 'tvtop / cctvtop', desc: 'Direct entry points for the training dashboards (same as hypernix tvtop / cctvtop).' },
  { cmd: 'tvtop-old / tvtop-plus-plus / tvtoppp', desc: 'Older TUI dashboard generations, kept for compatibility.' },
  { cmd: 'tvtop-older', desc: 'Original single-panel dashboard.' },
  { cmd: 'eth', desc: 'Ethanol GPU overclock / VRAM helper. Refuses to apply without --confirm.' },
  { cmd: 'hyped', desc: 'Configurable high-quality chat TUI with a model/persona configurator.' },
  { cmd: 'hyped-pro / hyped-plus', desc: 'Standalone Node.js TUI backed by a Python dispatch layer — cloud + local models, Gatekeeper routing, slash autocomplete, price estimator, /gui desktop mode.' },
  { cmd: 'hyped-pro-gui', desc: 'Launch the hyped-pro desktop GUI directly (Qt6 X11/Wayland, GTK4 fallback — install via the [gui] extra).' },
  { cmd: 'multilama', desc: 'Unified interface over multiple llama.cpp variants (vanilla, ik_llama.cpp, PrismML fork, KoboldCpp).' },
  { cmd: 'gkey', desc: 'Same as hypernix gkey, as its own executable.' },
  { cmd: 'hnx-map', desc: 'Same as hypernix map, as its own executable.' },
]

